import React, { useState } from 'react';
import { Pressable, StyleSheet, Text, View, useWindowDimensions } from 'react-native';

import { ProgressRing, StackedBarChart, type StackDay } from '../components/charts';
import { ConfirmModal } from '../components/forms';
import { FlameIcon, TrashIcon } from '../components/icons';
import { doneAmount, formatCN, formatDelta, forecastCompletion, lastNDays, recentLogs, streakInfo } from '../lib';
import { layout, palette } from '../theme';
import type { Log, StoreShape } from '../types';

type Mutate = (updater: (prev: StoreShape) => StoreShape) => void;

export function BoardScreen({ state, mutate, today }: { state: StoreShape; mutate: Mutate; today: string }) {
  const { width } = useWindowDimensions();
  const isDesktop = width >= 1000;
  const [deletingLog, setDeletingLog] = useState<Log | undefined>();

  const days = lastNDays(today, 14);
  const chart: StackDay[] = days.map((d) => {
    const byGoal: Record<string, number> = {};
    let total = 0;
    for (const l of state.logs) {
      if (l.date !== d || l.minutes == null) continue;
      byGoal[l.goalId] = (byGoal[l.goalId] ?? 0) + l.minutes;
      total += l.minutes;
    }
    return {
      date: d, label: `${Number(d.slice(5, 7))}/${Number(d.slice(8, 10))}`, total,
      segments: state.goals.filter((g) => byGoal[g.id]).map((g) => ({ id: g.id, color: g.color, value: byGoal[g.id] })),
    };
  });
  const anyMinutes = chart.some((d) => d.total > 0);

  const deleteLog = (log: Log) => mutate((prev) => ({ ...prev, logs: prev.logs.filter((l) => l.id !== log.id) }));

  return <View>
    <Text style={layout.title}>看板</Text>
    <Text style={layout.subtitle}>每个目标的进度环、核心数字、预案和最近记录</Text>
    <View style={[styles.boardGrid, isDesktop && styles.boardGridDesktop]}>
      {state.goals.map((g) => {
        const done = doneAmount(state.logs, g.id);
        const pct = Math.min(100, Math.round((done / g.total) * 100));
        const streak = streakInfo(state.logs, g.id, today).streak;
        const forecast = forecastCompletion(g, state.logs, today);
        const recent = recentLogs(state.logs, g.id, 10);
        return <View key={g.id} style={[styles.boardCard, isDesktop && styles.boardCardDesktop]} testID={`board-card-${g.id}`}>
          <View style={styles.boardHead}>
            <View style={[styles.colorBar, { backgroundColor: g.color }]} />
            <Text style={styles.boardName}>{g.name}</Text>
          </View>
          <View style={styles.ringRow}>
            <ProgressRing color={pct >= 100 ? palette.success : g.color} pct={pct} size={110}>
              <Text style={styles.ringPct}>{pct}%</Text>
              <Text style={styles.ringSub}>完成率</Text>
            </ProgressRing>
            <View style={styles.statCol}>
              <View style={styles.statBox} testID={`stat-done-${g.id}`}>
                <Text style={styles.statValue}>{done}<Text style={styles.statUnit}> / {g.total} {g.unit}</Text></Text>
                <Text style={styles.statLabel}>已完成量</Text>
              </View>
              <View style={styles.statBox} testID={`stat-streak-${g.id}`}>
                <View style={{ alignItems: 'center', flexDirection: 'row', gap: 5 }}>
                  <FlameIcon color={streak > 0 ? palette.warning : palette.muted} size={16} />
                  <Text style={styles.statValue}>{streak}<Text style={styles.statUnit}> 天</Text></Text>
                </View>
                <Text style={styles.statLabel}>连续打卡</Text>
              </View>
              <View style={styles.statBox} testID={`stat-forecast-${g.id}`}>
                <Text style={styles.statValue}>{forecast ? formatCN(forecast.date) : '暂无推算'}</Text>
                <Text style={styles.statLabel}>{forecast ? `预计完成 · ${formatDelta(forecast.delta)}` : '近 7 天打卡样本不足'}</Text>
              </View>
            </View>
          </View>
          {g.obstacle || g.coping ? <View style={styles.planBox} testID={`board-plan-${g.id}`}>
            {g.obstacle ? <Text style={styles.planText}>障碍：{g.obstacle}</Text> : null}
            {g.coping ? <Text style={styles.planText}>预案：{g.coping}</Text> : null}
          </View> : null}
          <Text style={styles.recentTitle}>最近 {recent.length} 条记录</Text>
          {recent.length === 0 ? <Text style={layout.caption}>还没有记录。</Text> : recent.map((l) => <View key={l.id} style={styles.logRow} testID={`log-row-${l.id}`}>
            <Text style={styles.logDate}>{formatCN(l.date)}</Text>
            {l.isBackfill ? <View style={styles.backfillTag}><Text style={styles.backfillTagText}>补</Text></View> : null}
            <Text style={styles.logAmount}>{l.amount} {g.unit}{l.minutes != null ? ` · ${l.minutes} 分钟` : ''}</Text>
            <Pressable accessibilityLabel={`删除 ${formatCN(l.date)} 的记录`} accessibilityRole="button" onPress={() => setDeletingLog(l)} style={styles.logDelete} testID={`delete-log-${l.id}`}>
              <TrashIcon color={palette.danger} size={14} />
            </Pressable>
          </View>)}
        </View>;
      })}
      {state.goals.length === 0 ? <View style={styles.boardCard}><Text style={layout.caption}>还没有目标，先去「今日」页新建一个。</Text></View> : null}
    </View>
    <View style={styles.chartCard}>
      <Text style={styles.chartTitle}>近 14 天投入分钟</Text>
      <Text style={layout.caption}>分目标堆叠，仅统计填写了分钟数的记录</Text>
      {anyMinutes ? <View style={{ marginTop: 12 }}><StackedBarChart days={chart} /></View> : <Text style={[layout.caption, { marginTop: 12 }]} testID="minutes-chart-empty">最近 14 天没有带分钟数的记录，图表不硬凑。</Text>}
      <View style={styles.legendRow}>
        {state.goals.map((g) => <View key={g.id} style={styles.legendItem}><View style={[styles.legendDot, { backgroundColor: g.color }]} /><Text style={styles.legendLabel}>{g.name}</Text></View>)}
      </View>
    </View>
    <ConfirmModal body={`删除 ${deletingLog ? formatCN(deletingLog.date) : ''} 的这条记录？连续天数与推算会按真实日期重新计算。`} confirmLabel="删除" danger onClose={() => setDeletingLog(undefined)} onConfirm={() => { if (deletingLog) deleteLog(deletingLog); setDeletingLog(undefined); }} testID="confirm-delete-log" title="删除记录？" visible={deletingLog != null} />
  </View>;
}

const styles = StyleSheet.create({
  boardGrid: { gap: 14, marginTop: 18 },
  boardGridDesktop: { flexDirection: 'row', flexWrap: 'wrap' },
  boardCard: { backgroundColor: palette.surface, borderColor: palette.border, borderRadius: 20, borderWidth: 1, gap: 12, padding: 18 },
  boardCardDesktop: { width: '48.5%' },
  boardHead: { alignItems: 'center', flexDirection: 'row', gap: 8 },
  colorBar: { borderRadius: 3, height: 18, width: 5 },
  boardName: { color: palette.ink, flex: 1, fontSize: 16, fontWeight: '800' },
  ringRow: { alignItems: 'center', flexDirection: 'row', gap: 16 },
  ringPct: { color: palette.ink, fontSize: 20, fontWeight: '800' },
  ringSub: { color: palette.muted, fontSize: 11, fontWeight: '700', marginTop: 1 },
  statCol: { flex: 1, gap: 10 },
  statBox: { gap: 2 },
  statValue: { color: palette.ink, fontSize: 18, fontWeight: '800' },
  statUnit: { color: palette.muted, fontSize: 12, fontWeight: '600' },
  statLabel: { color: palette.muted, fontSize: 12 },
  planBox: { backgroundColor: palette.canvas, borderRadius: 12, gap: 5, padding: 12 },
  planText: { color: palette.muted, fontSize: 12.5, lineHeight: 18 },
  recentTitle: { color: palette.ink, fontSize: 13, fontWeight: '800', marginTop: 2 },
  logRow: { alignItems: 'center', borderTopColor: palette.border, borderTopWidth: 1, flexDirection: 'row', gap: 8, paddingVertical: 9 },
  logDate: { color: palette.ink, fontSize: 13, fontWeight: '700', width: 62 },
  backfillTag: { backgroundColor: palette.warningSoft, borderColor: palette.warning, borderRadius: 6, borderWidth: 1, paddingHorizontal: 5, paddingVertical: 1 },
  backfillTagText: { color: palette.warning, fontSize: 10, fontWeight: '800' },
  logAmount: { color: palette.muted, flex: 1, fontSize: 13 },
  logDelete: { alignItems: 'center', height: 30, justifyContent: 'center', width: 30 },
  chartCard: { backgroundColor: palette.surface, borderColor: palette.border, borderRadius: 20, borderWidth: 1, gap: 4, marginTop: 16, padding: 18 },
  chartTitle: { color: palette.ink, fontSize: 16, fontWeight: '800' },
  legendRow: { flexDirection: 'row', flexWrap: 'wrap', gap: 12, marginTop: 12 },
  legendItem: { alignItems: 'center', flexDirection: 'row', gap: 6 },
  legendDot: { borderRadius: 4, height: 10, width: 10 },
  legendLabel: { color: palette.muted, fontSize: 12, fontWeight: '600' },
});
